type alien_individual = {
  is_lawful_permanent_resident_during_year : bool; (* clause (i): lawful permanent resident at any time during calendar year *)
  meets_substantial_presence_test : bool; (* clause (ii): substantial presence test of paragraph (3) *)
  makes_first_year_election : bool; (* clause (iii): election under paragraph (4) *)
}

(* 7701(b)(1)(A) - alien treated as US resident for calendar year iff (i), (ii), or (iii) holds *)
let is_resident_alien (alien : alien_individual) : bool =
  alien.is_lawful_permanent_resident_during_year ||
  alien.meets_substantial_presence_test ||
  alien.makes_first_year_election
